steps.script:
var d = tree.root.get_node("/root/AttackAssignmentDialog")
var t = d.get_node("Content/BreakdownScroll/BreakdownDisplay").get_parsed_text()
for w in ["ATTACKS", "HIT", "WOUND", "SAVE", "DAMAGE", "SLAIN"]:
	if not w in t:
		return "missing row: " + w
return "all rows"

var d = tree.root.get_node("/root/AttackAssignmentDialog")
var t = d.get_node("Content/BreakdownScroll/BreakdownDisplay").get_parsed_text()
for w in ["WS 3+", "S10 vs T6 → 3+", "Sv 2+ AP-2 → 4+"]:
	if not w in t:
		return "missing: " + w + " in: " + t
return "ok"

var d = tree.root.get_node("/root/AttackAssignmentDialog")
var t = d.get_node("Content/BreakdownScroll/BreakdownDisplay").get_parsed_text()
if not "Attack squig" in t:
	return "no table for the Extra Attacks weapon"
if not "Extra Attacks" in t:
	return "the Extra Attacks table is not labelled as one"
return "ok"

var d = tree.root.get_node("/root/AttackAssignmentDialog")
var bd = d._damage_breakdown("power_klaw_melee", "U_CUSTODIAN_GUARD_B", 1, "U_WARBOSS_B")
var chain = bd.total_attacks * bd.p_hit * bd.p_wound * bd.p_unsaved * bd.damage_avg * bd.p_damage_through
if abs(chain - bd.expected_damage) > 0.001:
	return "chain %.4f != E[D] %.4f" % [chain, bd.expected_damage]
if abs(bd.expected_damage - d._estimate_expected_damage("power_klaw_melee", "U_CUSTODIAN_GUARD_B", 1, "U_WARBOSS_B")) > 0.001:
	return "table disagrees with the assignment row"
return "%.2f" % bd.expected_damage

var d = tree.root.get_node("/root/AttackAssignmentDialog")
var t = d.get_node("Content/BreakdownScroll/BreakdownDisplay").get_parsed_text()
return "Not modelled" in t

var p = PhaseManager.get_current_phase_instance()
var out = []
for a in p.staged_fight_state["assignments"]:
	out.append(str(a.get("weapon", "?")))
return ",".join(out)

var d = tree.root.get_node("/root/AttackAssignmentDialog")
var t = d.get_node("Content/BreakdownScroll/BreakdownDisplay").get_parsed_text()
for w in ["Guardian spear", "S7 vs T5 → 3+", "Sv 4+ AP-2 → 6+"]:
	if not w in t:
		return "missing: " + w + " in: " + t
return "ok"

var d = tree.root.get_node("/root/AttackAssignmentDialog")
var t = d.get_node("Content/BreakdownScroll/BreakdownDisplay").get_parsed_text()
return "lost to overkill" in t

var d = tree.root.get_node("/root/AttackAssignmentDialog")
var wl = d.get_node("Content/GroupsScroll/GroupsBox/Group0/Body/WeaponList")
var want = -1
for i in range(wl.item_count):
	if str(wl.get_item_text(i)).begins_with("Misericordia"):
		want = i
if want < 0:
	return "no Misericordia offered"
wl.select(want)
wl.item_selected.emit(want)
return "ok"

var d = tree.root.get_node("/root/AttackAssignmentDialog")
var t = d.get_node("Content/BreakdownScroll/BreakdownDisplay").get_parsed_text()
if not "Misericordia" in t:
	return "table did not follow the weapon change"
if "Guardian spear" in t:
	return "stale Guardian spear table still rendered"
if not "S5 vs T5 → 4+" in t:
	return "missing the Misericordia wound line in: " + t
if "lost to overkill" in t:
	return "a 1-damage weapon cannot overkill a 1-wound model"
return "ok"
